using System;

namespace StdbModule;

public static partial class PolishQuotes
{
    public static class JerzyAndrzejewski
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://pl.wikiquote.org/wiki/Jerzy_Andrzejewski", Text = "Cieniem każdej miłości jest cierpienie. Nie można nie kochać, ale jeśli się nie kocha, miłość rozszczepia się na miłość i cierpienie.", Author = "Jerzy Andrzejewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Jerzy_Andrzejewski", Text = "Potrzeba gwałtu i okrucieństwa targają naturą człowieka, człowiek przed nimi ucieka, ucieka od samotności, boi się jej i wstydzi, potem w stadzie, silny i szalony, zadaje i szerzy gwałt, jest ślepy, jest głuchy, ale jest silny, ponieważ jest szalony, aż przychodzi chwila przebudzenia i wówczas człowiek znów zostaje sam, tylko o całą zbrodniczość opętania bardziej niż przedtem samotny.", Author = "Jerzy Andrzejewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Jerzy_Andrzejewski", Text = "Tylko miłość potrafi każdą rzecz, nawet najskromniejszą, uczynić piękną.", Author = "Jerzy Andrzejewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Jerzy_Andrzejewski", Text = "Uciekłem, ponieważ nad pewność posiadania silniej pociąga mnie niepewność poszukiwań, wczoraj, pozawczoraj, dzisiaj i zawsze kusiły mnie i wciąż kuszą niewiadome obszary czasu i przestrzeni, jakie się przede mną mogą otworzyć i jakie się niekiedy przede mną otwierają, one mnie niecierpliwie i nagląco wabią, ponieważ mogą zawierać w sobie wszystko, wiem, że kresem oczekiwań jest rozczarowanie, ale przecież, choćby złudny, wolę cień nadziei od jej nieuchronnej śmierci, każda zdobycz jest grobem nadziei, każde osiągnięcie jest grobem nadziei, czas zazdrośnie się zacieśnia wokół wszelkiego posiadania, tylko pragnienia, jakkolwiek i one muszą ulec zniszczeniu, użyczają nocom i dniom swobodniejszego oddechu…", Author = "Jerzy Andrzejewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Jerzy_Andrzejewski", Text = "O cóż właściwie chodzi? I tak nie ma ocalenia. Można oszaleć albo dobrowolnie siebie zniszczyć. To wszystko.", Author = "Jerzy Andrzejewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Jerzy_Andrzejewski", Text = "Jeśli starcie nie wybuchło zaraz, to dlatego, iż nie odchodzi się, gdy już się nie kocha. Jedna chwila odrywa człowieka od człowieka i jedno drgnięcie serca zrywa więzy, które splatały lata. Jest się już tak daleko, że nie czuje się nawet potrzeby porzucenia i odejścia. To z początku nie istnieje. Zresztą ta chwila decydująca pozostaje najczęściej nieznana. Odnajdujemy ją nieraz po latach dopiero, gdy wszystko się już dokonało i niczego zmienić nie można.", Author = "Jerzy Andrzejewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Jerzy_Andrzejewski", Text = "Mój synu, przecież nie wierzy się na zawsze, wierzy się ciągle na nowo. Tu gesty niczego nie uratują. Ani nawet słowa, ani nawet czyny, bo mogą kłamać. Jeśli stoi się wobec Boga, trzeba odrzucić wszelkie kłamstwo. To jest właśnie najtrudniejsze. (…) Kłamstwo świata, a przede wszystkim to nasze własne kłamstwo, którym jak puklerzem zasłaniamy się przed samym sobą.", Author = "Jerzy Andrzejewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Jerzy_Andrzejewski", Text = "Odczuwał potrzebę przyjaźni, jak każdy człowiek, który przyjaźni ofiarować nie jest w stanie. Będąc egoistą, lubił atmosferę serdeczności. Sam jej nawet dużo posiadał, dostatecznie jednak powierzchownej, aby go nic nie kosztowała i w niczym nie zobowiązywała. Za to najbłahsza krytyka, choćby została wypowiedziana lekko i w formie żartobliwej, wytrącała go z równowagi.", Author = "Jerzy Andrzejewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Jerzy_Andrzejewski", Text = "Gdyby ludzie szczerze wyrażali swoje myśli, większość ich musiałaby się kończyć znakiem zapytania.", Author = "Jerzy Andrzejewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Jerzy_Andrzejewski", Text = "Jeśli nie pasują szczegóły – należy przewrócić całość.", Author = "Jerzy Andrzejewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Jerzy_Andrzejewski", Text = "Każdy człowiek ma jakąś rację, tylko nie każda racja wychodzi na zdrowie.", Author = "Jerzy Andrzejewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Jerzy_Andrzejewski", Text = "Każdy na ziemi ma takie niebo, czyściec i piekło, na jakie zasługuje.", Author = "Jerzy Andrzejewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Jerzy_Andrzejewski", Text = "miłość jest jak mydło, ubywa jej przy używaniu.", Author = "Jerzy Andrzejewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Jerzy_Andrzejewski", Text = "Podziwiać można starość drugich, własna jest nieprzyzwoita.", Author = "Jerzy Andrzejewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Jerzy_Andrzejewski", Text = "polityka to nie jest praca, to są zajęcia, polityka stwarza sytuacje, a nie wartości (…)", Author = "Jerzy Andrzejewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Jerzy_Andrzejewski", Text = "Pogarda dla szmiry treściowej i artystycznej wydaje mi się równie niedorzeczna, jak niedorzeczną byłaby np. pogarda dla nawozu, który — być może — nie jest przyjemny w wyglądzie i w zapachu, jednak sprawia, że dzięki niemu świat roślinny uzyskuje bujną płodność.", Author = "Jerzy Andrzejewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Jerzy_Andrzejewski", Text = "sile (…) nie zawsze towarzyszy odwaga i odwrotnie, słabość nie musi być tchórzliwa.", Author = "Jerzy Andrzejewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Jerzy_Andrzejewski", Text = "Ale zgodzi się pan, że nie można czynów ludzkich mierzyć czasem, który mógłby być. Mierzy się je czasem, który jest. Trudno, takie jest prawo życia. Ludzie nie mają równych szans. Jedne pokolenia mogą w swoje ocalenie włożyć wysiłek mały, inne – wysiłek ponadludzki.", Author = "Jerzy Andrzejewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Jerzy_Andrzejewski", Text = "Bezsilność tak straszna, iż żadna rozpacz nie da się jej przyrównać. Coś z przegrania całego życia. Nieodwracalna klęska. Najchętniej bym spał. Noc, która mogłaby trwać dwadzieścia cztery godziny.", Author = "Jerzy Andrzejewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Jerzy_Andrzejewski", Text = "Dużo o tym wszystkim można mówić. I cóż ostatecznie pozostaje? To tylko, co człowiek czyni, nic więcej. Reszta może być prawdą, lecz może być także zwykłym kłamstwem, złudzeniem. Dopóki człowiek nie musi siebie sprawdzić w czynie, może się oszukiwać bez żadnych ograniczeń.", Author = "Jerzy Andrzejewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Jerzy_Andrzejewski", Text = "Honor to nie jest wierność samemu sobie.", Author = "Jerzy Andrzejewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Jerzy_Andrzejewski", Text = "Jeżeli bardzo się czegoś pragnie, jak można być pewnym?.", Author = "Jerzy Andrzejewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Jerzy_Andrzejewski", Text = "Naprawdę interesujące są tylko te książki, których żadne zdanie nie zostało jeszcze napisane.", Author = "Jerzy Andrzejewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Jerzy_Andrzejewski", Text = "Nie wybiera się przecież swojego czasu. I żaden czas nie dostosuje się do człowieka. To człowiek musi się dostosować. W przeciwnym przypadku ginie.", Author = "Jerzy Andrzejewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Jerzy_Andrzejewski", Text = "przechodniu<br />byłem kim jesteś<br />będziesz kim jestem<br />módlmy się za siebie nawzajem", Author = "Jerzy Andrzejewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Jerzy_Andrzejewski", Text = "Przekonał się dzisiaj, że zadanie bólu komuś, przez kogo się jest kochanym, wymaga wprawdzie pewnego wysiłku i przełamania się, lecz nie grozi następstwami przekraczającymi miłość.", Author = "Jerzy Andrzejewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Jerzy_Andrzejewski", Text = "To nie to samo. Nie wybiera się ojczyzny.<br />– Historii też się nie wybiera. Ale po to człowiek żyje, żeby przekształcać i ojczyznę, i historię.", Author = "Jerzy Andrzejewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Jerzy_Andrzejewski", Text = "Byłaby to nawet pewna pociecha, gdyby najgorsi byli odrobinę lepsi.", Author = "Jerzy Andrzejewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Jerzy_Andrzejewski", Text = "Człowiek słucha mózgiem, a nie uszami.", Author = "Jerzy Andrzejewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Jerzy_Andrzejewski", Text = "Ironia i szyderstwo wlane do pustych naczyń, stają się tylko mętną cieczą.", Author = "Jerzy Andrzejewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Jerzy_Andrzejewski", Text = "Można odejść od swoich miłości, lecz nie podobna zapomnieć, że się kochało.", Author = "Jerzy Andrzejewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Jerzy_Andrzejewski", Text = "Nie od cudzych grzechów włos na głowie siwieje…", Author = "Jerzy Andrzejewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Jerzy_Andrzejewski", Text = "Taka jest bowiem ludzka natura, że nie wobec opinii milionów, lecz pod spojrzeniem drugiego człowieka czuje się najbardziej obnażona.", Author = "Jerzy Andrzejewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Jerzy_Andrzejewski", Text = "W Polsce najgwałtowniej i najbezwzględniej potępia się ludzi nie za to, że źle czynią, lecz za to, że inaczej myślą.", Author = "Jerzy Andrzejewski" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Jerzy_Andrzejewski", Text = "Wierność wyczerpuje się, gdy nie jest oparta na miłości, na prawdziwej miłości.", Author = "Jerzy Andrzejewski" },
        };
    }
}